use super::*;
use common::qa_trace_scope::{TraceContext,TraceRequest};
use super::scoped::ScopedCapture;
use std::{path::PathBuf,time::Instant};
fn now()->u64{std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_millis()as u64}
fn fixture()->(TraceContext,PathBuf,PathBuf){static ID:AtomicU64=AtomicU64::new(1);let n=ID.fetch_add(1,Ordering::Relaxed);let root=std::env::var_os("CG_QA_TEST_EVIDENCE_DIR").map(PathBuf::from).unwrap_or_else(std::env::temp_dir);let dir=root.join(format!("scoped-gate-{}-{n}",std::process::id()));std::fs::create_dir(&dir).unwrap();let ctx=TraceContext{native_session_id:"native_test".into(),claim_id:"claim_test".into(),handoff_binding_id:"handoff_test".into(),rental_session_id:Some("rental_test".into()),connection_nonce:"a".repeat(32),generation:n,authority_expires_ms:now()+120000};let state=dir.join("rental.json");std::fs::write(&state,serde_json::json!({"PcId":"2","ClaimId":"claim_test","RentalSessionId":"rental_test"}).to_string()).unwrap();(ctx,dir,state)}
fn request(ctx:&TraceContext,dir:&std::path::Path,duration:u64){let r=TraceRequest{context:ctx.clone(),request_nonce:"b".repeat(32),expires_ms:now()+5000,duration_ms:duration};std::fs::write(dir.join("request.json"),serde_json::to_vec(&r).unwrap()).unwrap();}
async fn until(mut check:impl FnMut()->bool){let end=Instant::now()+std::time::Duration::from_secs(3);while !check(){assert!(Instant::now()<end,"test bounded wait");tokio::time::sleep(std::time::Duration::from_millis(20)).await;}}
fn ready(s:&ScopedCapture){let info=StreamInfo{ssrc:42,payload_type:98,mime_type:"video/H264".into(),clock_rate:90000,..Default::default()};s.bind(&info,1);for i in 1..=3{s.sent(42,1,i*3000,true);}}
#[tokio::test]async fn waits_for_ready_request_and_scope_then_starts_fresh_clock(){let(ctx,dir,state)=fixture();let s=ScopedCapture::start(ctx.clone(),dir.clone(),state.clone()).unwrap();request(&ctx,&dir,400);tokio::time::sleep(std::time::Duration::from_millis(500)).await;assert!(s.acquire().is_none());assert!(!dir.join("armed.json").exists());ready(&s);until(||s.acquire().is_some()).await;let tap=s.acquire().unwrap();assert!(tap.now_us()<300000);tap.record(tap.now_us(),tap.now_us(),Data::ReadError);until(||dir.join("gate-stopped.json").exists()).await;assert!(s.acquire().is_none());let text=std::fs::read_to_string(dir.join(format!("capture-{}.jsonl","b".repeat(32)))).unwrap();let head:serde_json::Value=serde_json::from_str(text.lines().next().unwrap()).unwrap();assert_eq!(head["parent_binding"]["context"]["rental_session_id"],"rental_test");assert_eq!(head["max_duration_ms"],400);}
#[tokio::test]async fn mismatched_claim_cannot_activate(){let(ctx,dir,state)=fixture();let s=ScopedCapture::start(ctx.clone(),dir.clone(),state).unwrap();ready(&s);let mut other=ctx.clone();other.claim_id="claim_other".into();request(&other,&dir,1000);tokio::time::sleep(std::time::Duration::from_millis(300)).await;assert!(s.acquire().is_none());assert!(!dir.join("armed.json").exists());s.close();}
#[tokio::test]async fn rental_change_stops_without_rearming(){let(ctx,dir,state)=fixture();let s=ScopedCapture::start(ctx.clone(),dir.clone(),state.clone()).unwrap();ready(&s);request(&ctx,&dir,5000);until(||s.acquire().is_some()).await;std::fs::write(&state,b"{}").unwrap();until(||dir.join("gate-stopped.json").exists()).await;assert!(s.acquire().is_none());std::fs::write(&state,serde_json::json!({"PcId":"2","ClaimId":"claim_test","RentalSessionId":"rental_test"}).to_string()).unwrap();tokio::time::sleep(std::time::Duration::from_millis(150)).await;assert!(s.acquire().is_none());}
#[tokio::test]async fn closed_scope_cannot_be_activated(){let(ctx,dir,state)=fixture();let s=ScopedCapture::start(ctx.clone(),dir.clone(),state).unwrap();ready(&s);s.close();request(&ctx,&dir,1000);until(||dir.join("gate-stopped.json").exists()).await;assert!(!dir.join("armed.json").exists());}
#[tokio::test]async fn stale_send_progress_never_arms(){let(ctx,dir,state)=fixture();let s=ScopedCapture::start(ctx.clone(),dir.clone(),state).unwrap();ready(&s);tokio::time::sleep(std::time::Duration::from_millis(1100)).await;request(&ctx,&dir,1000);tokio::time::sleep(std::time::Duration::from_millis(250)).await;assert!(s.acquire().is_none());s.close();}
#[tokio::test]async fn frame_attributes_observed_with_final_identity_and_wire_unchanged(){let(t,rx)=Tap::memory(16);let o=observer(t);let sink=Arc::new(Sink::default());let writer=o.bind_local_stream(&info(),sink.clone()).await;let sample=crate::transport::webrtc::recovery_frame::attach(vec![packet(),packet()],2);for s in &sample{writer.write(&s.packet,&s.attributes()).await.unwrap();}assert_eq!(sink.packets.lock().unwrap()[0].0,packet());let rows:Vec<_>=rx.try_iter().filter(|e|matches!(e.data,Data::FramePacket{..})).collect();assert_eq!(rows.len(),2);assert!(matches!(rows[1].data,Data::FramePacket{ssrc:42,seq:65535,index:1,count:2,reference:2,..}));}

#[tokio::test]async fn duplicate_and_backward_rtp_do_not_create_readiness(){let(ctx,dir,state)=fixture();let s=ScopedCapture::start(ctx.clone(),dir.clone(),state).unwrap();let info=StreamInfo{ssrc:42,payload_type:98,mime_type:"video/H264".into(),clock_rate:90000,..Default::default()};s.bind(&info,1);for rtp in [9000,6000,9000,3000,9000]{s.sent(42,1,rtp,true);}request(&ctx,&dir,1000);tokio::time::sleep(std::time::Duration::from_millis(250)).await;assert!(s.acquire().is_none());s.close();}
#[tokio::test]async fn new_video_binding_stops_existing_scope(){let(ctx,dir,state)=fixture();let s=ScopedCapture::start(ctx.clone(),dir.clone(),state).unwrap();ready(&s);request(&ctx,&dir,5000);until(||s.acquire().is_some()).await;s.bind(&StreamInfo{ssrc:43,payload_type:98,mime_type:"video/H264".into(),clock_rate:90000,..Default::default()},2);assert!(s.acquire().is_none());until(||dir.join("gate-stopped.json").exists()).await;}

#[tokio::test]async fn progress_snapshot_is_fresh_counts_all_packets_and_stops_during_capture(){let(ctx,dir,state)=fixture();let s=ScopedCapture::start(ctx.clone(),dir.clone(),state).unwrap();ready(&s);for _ in 0..50{s.sent(42,1,9000,false);}until(||dir.join("progress.json").exists()).await;let p:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(dir.join("progress.json")).unwrap()).unwrap();assert_eq!(p["process"],std::process::id());assert_eq!(p["ssrc"],42);assert_eq!(p["progress_frames"],3);assert_eq!(p["packets_sent"],53);assert!(p["packets_per_second"].as_f64().unwrap()>0.0);assert!(now()-p["observed_at_ms"].as_u64().unwrap()<1000);request(&ctx,&dir,1500);until(||s.acquire().is_some()).await;let before=std::fs::read(dir.join("progress.json")).unwrap();for i in 4..20{s.sent(42,1,i*3000,true);}tokio::time::sleep(std::time::Duration::from_millis(600)).await;assert_eq!(before,std::fs::read(dir.join("progress.json")).unwrap());s.close();}
